137	    private static final class ArticulationPointTraversal extends DepthFirstGraphAnalysis<ArrayList<Integer>> {
138	        private final int[] lowLink;
139	        private final boolean[] articulationPoint;
140	
141	        private ArticulationPointTraversal(Graph graph) {
142	            super(graph);
143	            this.lowLink = new int[graph.vertexCount()];
144	            this.articulationPoint = new boolean[graph.vertexCount()];
145	        }
146	
147	        @Override
148	        protected void onDiscoverVertex(int vertex, int parent) {
149	            lowLink[vertex] = discoveryTimeOf(vertex);
150	        }
151	
152	        @Override
153	        protected void afterChildTraversal(int vertex, int child, int parent) {
154	            lowLink[vertex] = Math.min(lowLink[vertex], lowLink[child]);
155	
156	            if (parent != ROOT_PARENT && lowLink[child] >= discoveryTimeOf(vertex)) {
157	                articulationPoint[vertex] = true;
158	            }
159	        }
160	
161	        @Override
162	        protected void onBackEdge(int vertex, int neighbor) {
163	            lowLink[vertex] = Math.min(lowLink[vertex], discoveryTimeOf(neighbor));
164	        }
165	
166	        @Override
167	        protected void onCompleteVertex(int vertex, int parent, int childCount) {
168	            if (parent == ROOT_PARENT && childCount > 1) {
169	                articulationPoint[vertex] = true;
170	            }
171	        }
172	
173	        @Override
174	        protected ArrayList<Integer> buildResult() {
175	            ArrayList<Integer> result = new ArrayList<>();
